function renderRecordConfidenceStrip(lang: SiteLang): string {
  const copy = recordStartCopy(lang);
  return `<div class="record-confidence-strip" aria-label="${escapeHtml(copy.confidenceAria)}">${copy.confidenceItems
    .map((item) => `<div class="record-confidence-item"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.body)}</span></div>`)
    .join("")}</div>`;
}

function renderRecordStartStateRow(copy: RecordStartCopy): string {
  return `<div class="start-guide-state-row" aria-label="${escapeHtml(copy.startStateAria)}">${copy.startStateItems
    .map((item) => `<span class="start-guide-state-chip"><span class="start-guide-state-dot" aria-hidden="true"></span>${escapeHtml(item)}</span>`)
    .join("")}</div>`;
}

function renderRecordFirstSuccess(copy: RecordPageCopy): string {
  return `<div class="record-first-success" aria-label="${escapeHtml(copy.firstSuccessAria)}"><strong>${escapeHtml(copy.firstSuccessLabel)}</strong><ol>${copy.firstSuccessItems
    .map((item) => `<li><span>${escapeHtml(item)}</span></li>`)
    .join("")}</ol></div>`;
}


type RecordRecoverySource = "" | "location_denied" | "login_required" | "draft_restore" | "media_retry" | "upload_failed" | "global_capture";
type RecordRecoveryStart = "" | "note" | "photo" | "video" | "gallery";
type RecordRecoveryState = {
  active: boolean;
  draft: boolean;
  retryMedia: boolean;
  source: RecordRecoverySource;
  start: RecordRecoveryStart;
};

type RecordRecoveryCopy = {
  pageTitle: string;
  eyebrow: string;
  guestTitle: string;
  guestBody: string;
  guestSafeTitle: string;
  guestSafeBody: string;
  loginAction: string;
  registerAction: string;
  recordsAction: string;
  mapAction: string;
  panelBadge: string;
  panelTitle: string;
  checkingTitle: string;
  checkingBody: string;
  readyTitle: string;
  readyBody: string;
  mediaRetryTitle: string;
  mediaRetryBody: string;
  emptyTitle: string;
  emptyBody: string;
  errorTitle: string;
  errorBody: string;
  discardedTitle: string;
  discardedBody: string;
  locationAction: string;
  saveAction: string;
  pickAction: string;
  backAction: string;
  discardAction: string;
  discardConfirm: string;
  footerNote: string;
};

const RECORD_RECOVERY_SOURCES = new Set<RecordRecoverySource>([
  "location_denied",
  "login_required",
  "draft_restore",
  "media_retry",
  "upload_failed",
  "global_capture",
]);

function resolveRecordRecoveryState(currentUrl = "/record"): RecordRecoveryState {
  let params = new URLSearchParams();
  try {
    params = new URL(currentUrl, "https://ikimon.local").searchParams;
  } catch {
    params = new URLSearchParams();
  }
  const rawStart = params.get("start") ?? "";
  const start: RecordRecoveryStart = rawStart === "note" || rawStart === "photo" || rawStart === "video" || rawStart === "gallery" ? rawStart : "";
  const draft = params.get("draft") === "1";
  const retryMedia = params.get("retry") === "media";
  const rawSource = (params.get("source") ?? "").trim() as RecordRecoverySource;
  let source: RecordRecoverySource = RECORD_RECOVERY_SOURCES.has(rawSource) ? rawSource : "";
  if (retryMedia) source = "media_retry";
  if (draft && !source) source = "draft_restore";
  return {
    active: draft || retryMedia || Boolean(source),
    draft,
    retryMedia,
    source,
    start,
  };
}

function appendRecordRecoveryParams(params: URLSearchParams, state: RecordRecoveryState, lang: SiteLang): void {
  if (state.start) params.set("start", state.start);
  if (state.draft) params.set("draft", "1");
  if (state.retryMedia) params.set("retry", "media");
  if (state.source) params.set("source", state.source);
  if (lang) params.set("lang", lang);
}

