function renderRecordRecoveryPanel(copy: RecordRecoveryCopy, state: RecordRecoveryState, recordsHref: string, mapHref: string): string {
  return `<section class="record-recovery-panel" data-record-recovery data-source="${escapeHtml(state.source || "draft_restore")}" data-state="checking" aria-labelledby="record-recovery-title">
    <div class="record-recovery-panel-top">
      <span class="record-recovery-badge">${escapeHtml(copy.panelBadge)}</span>
      <div class="record-recovery-utility-actions">
        <button type="button" data-record-recovery-back>${escapeHtml(copy.backAction)}</button>
        <button type="button" data-record-recovery-discard>${escapeHtml(copy.discardAction)}</button>
      </div>
    </div>
    <strong id="record-recovery-title">${escapeHtml(copy.panelTitle)}</strong>
    <p id="record-recovery-body">${escapeHtml(copy.checkingBody)}</p>
    <div class="record-recovery-actions">
      <button type="button" class="record-recovery-location" data-record-recovery-location disabled>${escapeHtml(copy.locationAction)}</button>
      <button type="button" class="record-recovery-save" data-record-recovery-save disabled>${escapeHtml(copy.saveAction)}</button>
      <button type="button" class="record-recovery-pick" data-record-recovery-pick>${escapeHtml(copy.pickAction)}</button>
    </div>
    <div class="record-recovery-links"><a href="${escapeHtml(recordsHref)}">${escapeHtml(copy.recordsAction)}</a><a href="${escapeHtml(mapHref)}">${escapeHtml(copy.mapAction)}</a></div>
  </section>`;
}

function renderRecordStartGuide(basePath: string, lang: SiteLang, currentUrl = "/record"): string {
  const copy = recordStartCopy(lang);
  const recovery = resolveRecordRecoveryState(currentUrl);
  const recoveryCopy = recordRecoveryCopy(lang, recovery);
  const recordParams = new URLSearchParams();
  appendRecordRecoveryParams(recordParams, recovery, lang);
  const recordTarget = `/record${recordParams.toString() ? `?${recordParams.toString()}` : ""}`;
  const recordTargetForStart = (kind: "note" | "photo" | "video" | "gallery") => {
    const params = new URLSearchParams();
    const nextState: RecordRecoveryState = {
      ...recovery,
      start: kind,
      draft: recovery.draft && (!recovery.start || recovery.start === kind),
    };
    appendRecordRecoveryParams(params, nextState, lang);
    return `/record?${params.toString()}`;
  };
  const loginFor = (target: string) => appendLangToHref(withBasePath(basePath, `/login?redirect=${encodeURIComponent(target)}`), lang);
  const loginHref = loginFor(recovery.start ? recordTarget : recordTargetForStart("photo"));
  const memoHref = loginFor(recordTargetForStart("note"));
  const registerHref = appendLangToHref(withBasePath(basePath, `/register?redirect=${encodeURIComponent(recordTarget)}`), lang);
  const learnHref = appendLangToHref(withBasePath(basePath, "/learn"), lang);
  const mapHref = appendLangToHref(withBasePath(basePath, "/map"), lang);
  const publicFindsHref = appendLangToHref(withBasePath(basePath, "/records?view=public"), lang);

  if (recovery.active) {
    return renderSiteDocument({
      basePath,
      title: recoveryCopy.pageTitle,
      activeNav: copy.activeNav,
      lang,
      currentPath: appendLangToHref(withBasePath(basePath, recordTarget), lang),
      extraStyles: `${START_STATE_STYLES}\n${RECORD_RECOVERY_START_STYLES}`,
      body: `<div class="record-recovery-start" data-record-recovery-start data-source="${escapeHtml(recovery.source || "draft_restore")}">
        <section class="record-recovery-start-card">
          <div class="eyebrow">${escapeHtml(recoveryCopy.eyebrow)}</div>
          <h1>${escapeHtml(recoveryCopy.guestTitle)}</h1>
          <p>${escapeHtml(recoveryCopy.guestBody)}</p>
          <div class="record-recovery-assurance"><strong>${escapeHtml(recoveryCopy.guestSafeTitle)}</strong><span>${escapeHtml(recoveryCopy.guestSafeBody)}</span></div>
          <div class="record-recovery-start-actions">
            <a class="btn btn-solid" href="${escapeHtml(loginHref)}">${escapeHtml(recoveryCopy.loginAction)}</a>
            <a class="btn btn-ghost" href="${escapeHtml(registerHref)}">${escapeHtml(recoveryCopy.registerAction)}</a>
          </div>
          <div class="record-recovery-start-links"><a href="${escapeHtml(publicFindsHref)}">${escapeHtml(recoveryCopy.recordsAction)}</a><a href="${escapeHtml(mapHref)}">${escapeHtml(recoveryCopy.mapAction)}</a></div>
        </section>
      </div>`,
      footerNote: recoveryCopy.footerNote,
      shellClassName: "shell-record-recovery-start",
      hideGlobalRecordLauncher: true,
      hideFooter: true,
      minimalChrome: true,
    });
  }

  const qaHint = process.env.ALLOW_QUERY_USER_ID === "1"
    ? `<p class="meta" style="margin-top:14px;font-size:12px;color:#64748b">staging QA: <code>${escapeHtml(withBasePath(basePath, "/record?userId=..."))}</code></p>`
    : "";
  return renderSiteDocument({
    basePath,
    title: copy.title,
    activeNav: copy.activeNav,
    lang,
    currentPath: appendLangToHref(withBasePath(basePath, "/record"), lang),
    extraStyles: START_STATE_STYLES,
    hero: {
      eyebrow: copy.heroEyebrow,
      heading: copy.heroHeading,
      lead: copy.heroLead,
      tone: "light",
      align: "center",
      actions: [
        { href: loginHref, label: copy.photoAction },
        { href: registerHref, label: copy.registerAction, variant: "secondary" },
      ],
    },
    body: `<div class="start-guide">
      <section class="section">
        <div class="start-guide-panel">
          <div class="eyebrow">${escapeHtml(copy.panelEyebrow)}</div>
          <h2>${escapeHtml(copy.panelHeading)}</h2>
          <p>${escapeHtml(copy.panelBody)}</p>
          ${renderRecordStartStateRow(copy)}
          <div class="start-guide-browse-actions" aria-label="${escapeHtml(copy.browseAria)}">
            <a class="btn btn-ghost" href="${escapeHtml(mapHref)}">${escapeHtml(copy.mapAction)}</a>
            <a class="btn btn-ghost" href="${escapeHtml(publicFindsHref)}">${escapeHtml(copy.publicFindsAction)}</a>
          </div>
          <div class="start-guide-actions">
            <a class="btn btn-solid" href="${escapeHtml(loginHref)}">${escapeHtml(copy.photoAction)}</a>
            <a class="btn btn-ghost" href="${escapeHtml(memoHref)}">${escapeHtml(copy.noteAction)}</a>
            <a class="btn btn-ghost" href="${escapeHtml(learnHref)}">${escapeHtml(copy.learnAction)}</a>
          </div>
          ${qaHint}
        </div>
      </section>
    </div>`,
    footerNote: copy.footerNote,
    shellClassName: "shell-record-start",
  });
}

type ObservationShotFeedbackItem = {
  role: string;
  icon: string;
  target: string;
  rationale: string;
  priority: "high" | "medium" | null;
};

type ObservationShotFeedbackGroup = {
  key: string;
  name: string;
  items: ObservationShotFeedbackItem[];
};

function shotFeedbackGroupName(subject: ObservationVisitSubject): string {
  return observationDetailUiName(subject.aiAssessment?.recommendedTaxonName ?? subject.displayName ?? subject.scientificName ?? "この対象");
}

function normalizeShotFeedbackKey(value: string): string {
  return value.trim().replace(/\s+/g, " ").toLowerCase();
}

function shotFeedbackBenefitText(options: {
  role: string;
  target: string;
  rationale?: string | null;
}): string {
  const role = normalizeShotFeedbackKey(options.role);
  const target = normalizeShotFeedbackKey(options.target);
  const rationale = normalizeShotFeedbackKey(options.rationale ?? "");
  const combined = `${role} ${target} ${rationale}`;

  if (role.includes("生息環境") || role.includes("広角") || role.includes("habitat") || rationale.includes("文脈")) {
    return "周りの草、水辺、日当たりなどが残ると、その場所でどう現れていたかを季節や別地点の記録と比べやすくなります。";
  }
  if (role.includes("基質") || role.includes("substrate") || combined.includes("土") || combined.includes("石") || combined.includes("樹皮")) {
    return "接している土、石、樹皮などが残ると、その生きものが使っていた場所の条件を後から読み返せます。";
  }
  if (role.includes("スケール") || role.includes("scale") || combined.includes("大きさ")) {
    return "大きさの手がかりがあると、写真だけでは迷いやすいサイズ感を後から確認できます。";
  }
  if (role.includes("全景") || role.includes("全身") || role.includes("full")) {
    return "全体の形と周りとの位置関係が残ると、アップだけでは分からない姿や広がりを見直せます。";
  }
  if (role.includes("部位") || role.includes("close") || rationale.includes("詳細")) {
    if (combined.includes("花") || combined.includes("花弁") || combined.includes("裂片") || combined.includes("萼")) {
      return "花の形や割れ方を後から見比べられて、似た花との違いや季節ごとの姿を説明しやすくなります。";
    }
    if (combined.includes("葉") || combined.includes("茎") || combined.includes("毛")) {
      return "葉や茎の付き方、毛の有無が残ると、同じ仲間の違いや成長段階を後から見直せます。";
    }
    if (combined.includes("翅") || combined.includes("触角") || combined.includes("脚") || combined.includes("昆虫")) {
      return "細部の形を後から拡大して見直せるので、その場では気づかなかった手がかりを拾いやすくなります。";
    }
    return "細部が残ると、後から見直したときに何が写っていて何が足りないかを判断しやすくなります。";
  }
  if (rationale.includes("特定") || rationale.includes("同定")) {
    return "後から見返す人が、見えている手がかりと保留すべき点を分けて考えやすくなります。";
  }
  if (options.rationale && !/詳細|文脈記録|記録するため/.test(options.rationale)) {
    return friendlyObservationText(options.rationale, 86);
  }
  return "その場の見え方がもう少し残ると、あとで読み返したときに場面や変化を思い出しやすくなります。";
}

function shotSuggestionFeedbackItem(suggestion: ShotSuggestion): ObservationShotFeedbackItem {
  const meta = SHOT_ROLE_META[suggestion.role] ?? { icon: "📸", label: suggestion.role };
  return {
    role: meta.label,
    icon: meta.icon,
    target: suggestion.target,
    rationale: shotFeedbackBenefitText({
      role: meta.label,
      target: suggestion.target,
      rationale: suggestion.rationale,
    }),
    priority: suggestion.priority,
  };
}

function candidateReadingFeedbackItems(reading: CandidateReading): ObservationShotFeedbackItem[] {
  const role = friendlyObservationText(reading.role || "次の見方", 22);
  return reading.shootingTips.map((tip) => ({
    role,
    icon: "💡",
    target: tip,
    rationale: shotFeedbackBenefitText({ role, target: tip }),
    priority: null,
  }));
}

function collectObservationShotFeedbackGroups(bundle: ObservationVisitBundle): ObservationShotFeedbackGroup[] {
  const groups: ObservationShotFeedbackGroup[] = [];
  const itemKeys = new Set<string>();
  const ensureGroup = (key: string, name: string): ObservationShotFeedbackGroup => {
    const normalized = normalizeShotFeedbackKey(key || name);
    const existing = groups.find((group) => group.key === normalized);
    if (existing) return existing;
    const group = { key: normalized, name: observationDetailUiName(name), items: [] };
    groups.push(group);
    return group;
  };
  const pushItem = (group: ObservationShotFeedbackGroup, item: ObservationShotFeedbackItem): void => {
    const target = friendlyObservationText(item.target, 64);
    if (!target) return;
    const rationale = friendlyObservationText(item.rationale, 80);
    const key = normalizeShotFeedbackKey(`${group.key}:${item.role}:${target}:${rationale}`);
    if (itemKeys.has(key)) return;
    itemKeys.add(key);
    group.items.push({ ...item, target, rationale });
  };

  for (const subject of bundle.subjects) {
    const group = ensureGroup(subject.occurrenceId, shotFeedbackGroupName(subject));
    for (const suggestion of subject.aiAssessment?.shotSuggestions ?? []) {
      pushItem(group, shotSuggestionFeedbackItem(suggestion));
    }
    for (const reading of subject.aiAssessment?.candidateReadings ?? []) {
      const readingGroup = ensureGroup(reading.scientificName || reading.name, reading.name);
      for (const item of candidateReadingFeedbackItems(reading)) {
        pushItem(readingGroup, item);
      }
    }
  }

  const readings = candidateReadingMap(bundle);
  for (const candidate of bundle.aiCandidates) {
    const reading = findCandidateReading(readings, [candidate.displayName, candidate.scientificName]);
    if (!reading || reading.shootingTips.length === 0) continue;
    const group = ensureGroup(reading.scientificName || reading.name || candidate.displayName, candidate.displayName);
    for (const item of candidateReadingFeedbackItems(reading)) {
      pushItem(group, item);
    }
  }

  return groups.filter((group) => group.items.length > 0);
}

function renderShotFeedbackItem(item: ObservationShotFeedbackItem, glossaryTerms: GlossaryTermHint[] = []): string {
  const priorityBadge = item.priority === "high"
    ? `<span class="obs-shot-pri obs-shot-pri-high">優先して残す</span>`
    : item.priority === "medium"
      ? `<span class="obs-shot-pri obs-shot-pri-medium">余裕があれば</span>`
      : "";
  return `<li class="obs-shot-item">
    <span class="obs-shot-role"><span class="obs-shot-icon">${escapeHtml(item.icon)}</span>${escapeHtml(item.role)}</span>
    <span class="obs-shot-target">${renderGlossaryText(item.target, glossaryTerms)}</span>
    ${item.rationale ? `<span class="obs-shot-rationale">${renderGlossaryText(item.rationale, glossaryTerms)}</span>` : ""}
    ${priorityBadge}
  </li>`;
}

function renderObservationShotFeedbackSurface(
  bundle: ObservationVisitBundle,
  mediaContext: ObservationMediaCopyContext = photoOnlyMediaContext(),
  glossaryTerms: GlossaryTermHint[] = [],
): string {
  const groups = collectObservationShotFeedbackGroups(bundle);
  if (groups.length === 0) return "";
  const mediaCopy = observationMediaCopy(mediaContext);
  const groupList = groups.map((group) => `<li class="obs-shot-group">
    <div class="obs-shot-group-head">
      <span class="obs-shot-group-name">${escapeHtml(group.name)}</span>
      <span class="obs-shot-group-count">${group.items.length}件</span>
    </div>
    <ul class="obs-shot-list">${group.items.map((item) => renderShotFeedbackItem(item, glossaryTerms)).join("")}</ul>
  </li>`).join("");
  return `<section class="section obs-surface-shot-feedback" data-obs-section="shot-feedback">
    <section class="obs-shot-card" aria-label="${escapeHtml(mediaCopy.shotAriaLabel)}">
      <div class="obs-shot-head">
        <div>
          <div class="obs-hint-eyebrow">${escapeHtml(mediaCopy.shotHeading)}</div>
          <p class="obs-hint-reminder">${escapeHtml(mediaCopy.shotReminder)}</p>
        </div>
      </div>
      <ul class="obs-shot-group-list">${groupList}</ul>
    </section>
  </section>`;
}

function renderSubjectComparison(bundle: ObservationVisitBundle, subject: ObservationVisitSubject): string {
  if (!bundle.selectedRun && !bundle.previousRun) {
    return "";
  }
  const current = subject.aiAssessment;
  const previous = subject.previousAiAssessment;
  const currentText = current
    ? `${observationDetailUiName(current.recommendedTaxonName ?? subject.displayName)} / ${confidenceLabel(current.confidenceBand)}`
    : "今回はまだヒントがありません";
  const previousText = previous
    ? `${observationDetailUiName(previous.recommendedTaxonName ?? subject.displayName)} / ${confidenceLabel(previous.confidenceBand)}`
    : "前のヒントはまだありません";
  return `<details class="obs-fold">
    <summary>前の候補を見る <span class="obs-fold-count">確認中</span></summary>
    <div class="obs-hint-sub">
      <div class="obs-hint-eye">今回の見え方</div>
      <p>${escapeHtml(currentText)}</p>
      ${bundle.selectedRun ? `<p class="obs-hint-foot">自動メモ: ${escapeHtml(bundle.selectedRun.generatedAt)}</p>` : ""}
    </div>
    <div class="obs-hint-sub">
      <div class="obs-hint-eye">前の候補</div>
      <p>${escapeHtml(previousText)}</p>
      ${bundle.previousRun ? `<p class="obs-hint-foot">自動メモ: ${escapeHtml(bundle.previousRun.generatedAt)}</p>` : ""}
    </div>
  </details>`;
}

function renderAiCandidates(bundle: ObservationVisitBundle): string {
  if (bundle.aiCandidates.length === 0) {
    return "";
  }
  return `<details class="obs-fold">
    <summary>ほかの自動候補 <span class="obs-fold-count">${bundle.aiCandidates.length}</span></summary>
    <div class="obs-nearby-grid">
      ${bundle.aiCandidates.map((candidate) => `
        <div class="obs-nearby-card">
          <div class="obs-nearby-body">
            <div class="obs-nearby-name">${escapeHtml(observationDetailUiName(candidate.displayName))}</div>
            <div class="obs-nearby-meta">${escapeHtml([
              publicRankHint(candidate.rank) || null,
              typeof candidate.confidence === "number" ? `${Math.round(candidate.confidence * 100)}%` : null,
              candidate.candidateStatus === "matched" && candidate.suggestedOccurrenceId ? "記録済み" : "候補",
            ].filter(Boolean).join(" · "))}</div>
            ${candidate.note ? `<p class="obs-id-note">${escapeHtml(candidate.note)}</p>` : ""}
          </div>
        </div>`).join("")}
    </div>
  </details>`;
}

export function renderIdentificationCandidateSwitch(options: {
  basePath: string;
  lang: SiteLang;
  bundle?: ObservationVisitBundle | null;
  currentSubject?: ObservationVisitSubject | null;
  targetLabel: string;
  candidateStatus: string;
}): string {
  const subjectIds = new Set<string>();
  const candidates: Array<{
    key: string;
    label: string;
    status: string;
    href: string | null;
    panelKey: string | null;
    subjectId: string | null;
    isCurrent: boolean;
    isWeak: boolean;
  }> = [];
  const addCandidate = (candidate: {
    key: string;
    label: string;
    status: string;
    rank?: string | null;
    scientificName?: string | null;
    href?: string | null;
    panelKey?: string | null;
    subjectId?: string | null;
    isCurrent?: boolean;
  }) => {
    const label = observationDetailUiName(candidate.label);
    const key = candidate.key || `${label}:${candidates.length}`;
    if (!isIdentificationCandidateLike({ name: label, rank: candidate.rank, scientificName: candidate.scientificName })) return;
    if (!label || candidates.some((item) => item.key === key || item.label === label)) return;
    candidates.push({
      key,
      label,
      status: candidate.status,
      href: candidate.href ?? null,
      panelKey: candidate.panelKey ?? null,
      subjectId: candidate.subjectId ?? null,
      isCurrent: Boolean(candidate.isCurrent),
      isWeak: false,
    });
  };

  if (options.bundle) {
    for (const subject of options.bundle.subjects) {
      subjectIds.add(subject.occurrenceId);
      const display = formatTaxonDisplayName(subject, options.lang).primaryLabel;
      addCandidate({
        key: `subject:${subject.occurrenceId}`,
        label: display,
        rank: subjectIdentificationRank(subject),
        scientificName: subject.scientificName,
        status: candidateStatusWithRank(display, subjectIdentificationRank(subject), subject.identificationCount > 0 ? "確認あり" : "確認待ち"),
        href: appendLangToHref(
          withBasePath(options.basePath, buildObservationDetailPath(options.bundle.visitId, subject.occurrenceId)),
          options.lang,
        ),
        panelKey: subject.occurrenceId,
        subjectId: subject.occurrenceId,
        isCurrent: subject.occurrenceId === options.currentSubject?.occurrenceId,
      });
    }
    for (const candidate of options.bundle.aiCandidates) {
      const occurrenceHref = candidate.suggestedOccurrenceId && subjectIds.has(candidate.suggestedOccurrenceId)
        ? appendLangToHref(
            withBasePath(options.basePath, buildObservationDetailPath(options.bundle.visitId, candidate.suggestedOccurrenceId)),
            options.lang,
          )
        : null;
      addCandidate({
        key: `candidate:${candidate.candidateId}`,
        label: candidate.displayName,
        rank: candidate.rank,
        scientificName: candidate.scientificName,
        status: candidateStatusWithRank(candidate.displayName, candidate.rank, candidate.suggestedOccurrenceId ? "記録済み" : typeof candidate.confidence === "number" ? `${Math.round(candidate.confidence * 100)}%` : "候補"),
        href: occurrenceHref,
        panelKey: occurrenceHref ? candidate.suggestedOccurrenceId : aiCandidatePanelKey(candidate),
        subjectId: occurrenceHref ? candidate.suggestedOccurrenceId : null,
        isCurrent: false,
      });
    }
  }

  if (candidates.length === 0) {
    addCandidate({
      key: "current",
      label: options.targetLabel,
      status: options.candidateStatus,
      panelKey: options.currentSubject?.occurrenceId ?? null,
      subjectId: options.currentSubject?.occurrenceId ?? null,
      isCurrent: true,
    });
  }
  if (!candidates.some((candidate) => candidate.isCurrent) && isIdentificationCandidateLike({ name: options.targetLabel })) {
    candidates.unshift({
      key: "current",
      label: options.targetLabel,
      status: options.candidateStatus,
      href: null,
      panelKey: options.currentSubject?.occurrenceId ?? null,
      subjectId: options.currentSubject?.occurrenceId ?? null,
      isCurrent: true,
      isWeak: false,
    });
  }

  const usefulCount = candidates.filter((candidate) => !candidate.isWeak).length;
  const currentIndex = Math.max(0, candidates.findIndex((candidate) => candidate.isCurrent));
  const isDenseCandidateList = candidates.length >= 5;
  const meterLabel = usefulCount > 0 ? "AI候補" : "候補名が弱い";
  const meterValue = usefulCount > 0
    ? (candidates.some((candidate) => candidate.isCurrent) ? `${currentIndex + 1}/${candidates.length}` : `${usefulCount}件`)
    : "0件";
  const warning = usefulCount === 0
    ? `<p class="obs-frame-candidate-warning">今の自動候補は「未同定」や植栽構造の粗いラベルだけです。名前候補としては不足しているため、別候補か追加証拠を足す前提で扱います。</p>`
    : "";

  const chips = candidates.map((candidate, index) => {
    const className = `obs-frame-candidate${candidate.isCurrent ? " is-current" : ""}${candidate.isWeak ? " is-weak" : ""}`;
    const body = `<strong>${escapeHtml(candidate.label)}</strong><span>${escapeHtml(candidate.status)}</span><small class="obs-frame-candidate-current">選択中</small>`;
    const searchText = `${candidate.label} ${candidate.status}`;
    const searchAttrs = ` data-ai-candidate-chip="1" data-ai-candidate-search-text="${escapeHtml(searchText)}"`;
    if (candidate.href && !candidate.isCurrent) {
      const subjectAttrs = candidate.subjectId
        ? ` data-subject-switch="1" data-subject-id="${escapeHtml(candidate.subjectId)}"`
        : "";
      return `<a class="${className}" href="${escapeHtml(candidate.href)}"${subjectAttrs}${searchAttrs}>${body}</a>`;
    }
    const targetAttrs = candidate.panelKey
      ? ` data-ai-target="${escapeHtml(candidate.panelKey)}" data-ai-candidate-index="${escapeHtml(String(index + 1))}" data-ai-candidate-total="${escapeHtml(String(candidates.length))}"`
      : "";
    return `<button class="${className}" type="button"${targetAttrs}${searchAttrs} aria-pressed="${candidate.isCurrent ? "true" : "false"}"${candidate.isCurrent ? ' aria-current="true"' : ""}>${body}</button>`;
  }).join("");
  const search = isDenseCandidateList
    ? `<label class="obs-frame-candidate-search"><span>候補名検索</span><input type="search" placeholder="候補名で絞り込み" autocomplete="off" data-ai-candidate-search></label>`
    : "";

  return `<div class="obs-frame-candidate-switch${usefulCount === 0 ? " is-weak" : ""}${isDenseCandidateList ? " is-dense" : ""}">
      <div class="obs-frame-candidate-meter"><span>${escapeHtml(meterLabel)}</span><strong data-ai-candidate-meter-value>${escapeHtml(meterValue)}</strong></div>
      ${search}
      <div class="obs-frame-identify-candidates" aria-label="AI候補" data-ai-candidate-list="1">
        ${chips}
      </div>
      ${isDenseCandidateList ? `<div class="obs-frame-candidate-empty" data-ai-candidate-empty hidden>該当する候補がありません</div>` : ""}
      ${warning}
    </div>`;
}

function normalizeCandidateReadingKey(value: string | null | undefined): string {
  return String(value ?? "").trim().toLowerCase();
}

function candidateReadingMap(bundle: ObservationVisitBundle): Map<string, CandidateReading> {
  const map = new Map<string, CandidateReading>();
  for (const subject of bundle.subjects) {
    for (const reading of subject.aiAssessment?.candidateReadings ?? []) {
      const keys = [reading.name, reading.scientificName].map(normalizeCandidateReadingKey).filter(Boolean);
      for (const key of keys) {
        if (!map.has(key)) map.set(key, reading);
      }
    }
  }
  return map;
}

function findCandidateReading(
  map: Map<string, CandidateReading>,
  names: Array<string | null | undefined>,
): CandidateReading | null {
  for (const name of names) {
    const hit = map.get(normalizeCandidateReadingKey(name));
    if (hit) return hit;
  }
  return null;
}

