function renderProfileSavedRecordPulse(basePath: string, lang: SiteLang, snapshot: ProfileSnapshot): string {
  const copy = profileSavedRecordCopy(lang);
  const latest = snapshot.recentObservations[0] ?? null;
  const recordHref = appendLangToHref(withBasePath(basePath, "/record"), lang);
  const recordsHref = appendLangToHref(withBasePath(basePath, "/records?view=mine"), lang);
  const lastRecordLabel = latest ? formatProfileDate(latest.observedAt) : formatProfileDate(snapshot.stats.firstObservedAt);
  const statsHtml = `<div class="profile-saved-record-stats" aria-label="記録史の要約">
    <small><b>${escapeHtml(formatProfileNumber(snapshot.stats.totalObservations))}</b>記録</small>
    <small><b>${escapeHtml(formatProfileNumber(snapshot.stats.uniqueTaxaAllTime))}</b>種</small>
    <small><b>${escapeHtml(lastRecordLabel)}</b>最終</small>
  </div>`;
  if (!latest) {
    return `<section class="section" data-testid="profile-saved-record-pulse">
      <div class="profile-saved-record-pulse is-empty">
        <div>
          <span>${escapeHtml(copy.emptyEyebrow)}</span>
          <strong>${escapeHtml(copy.emptyTitle)}</strong>
          <p>${escapeHtml(copy.emptyBody)}</p>
          ${statsHtml}
        </div>
        <a href="${escapeHtml(recordHref)}" data-kpi-action="profile:saved_record:first_record">${escapeHtml(copy.emptyCta)}</a>
      </div>
    </section>`;
  }
  const latestHref = appendLangToHref(profileObservationHref(basePath, latest), lang);
  const title = formatTaxonDisplayName(latest, lang).primaryLabel;
  const place = formatPlaceDisplay(latest, lang, "owner") || copy.noPlace;
  const date = formatProfileDate(latest.observedAt);
  return `<section class="section" data-testid="profile-saved-record-pulse">
    <div class="profile-saved-record-pulse">
      <div>
        <span>${escapeHtml(copy.savedEyebrow)}</span>
        <strong>${escapeHtml(copy.savedTitlePrefix)} ${escapeHtml(title)}</strong>
        <p>${escapeHtml(`${copy.savedBodyPrefix} ${date} · ${place}`)}</p>
        ${statsHtml}
      </div>
      <div class="profile-saved-record-actions">
        <a class="is-primary" href="${escapeHtml(latestHref)}" data-kpi-action="profile:saved_record:latest">${escapeHtml(copy.savedCta)}</a>
        <a href="${escapeHtml(recordsHref)}" data-kpi-action="profile:saved_record:records">${escapeHtml(copy.recordsCta)}</a>
      </div>
    </div>
  </section>`;
}

function renderChannelMediaCard(
  href: string,
  label: string,
  title: string,
  body: string,
  photoUrl: string | null | undefined,
  fallback: string,
): string {
  const mediaUrl = photoUrl ? (toThumbnailUrl(photoUrl, "md") ?? photoUrl) : null;
  return `<a class="profile-channel-card" href="${escapeHtml(href)}">
    <span class="profile-channel-media">
      ${mediaUrl
        ? `<img src="${escapeHtml(mediaUrl)}" alt="${escapeHtml(title)}" loading="lazy" decoding="async" onerror="this.hidden=true;this.nextElementSibling.hidden=false" /><span hidden>${escapeHtml(fallback)}</span>`
        : `<span>${escapeHtml(fallback)}</span>`}
    </span>
    <span class="profile-channel-body">
      <small>${escapeHtml(label)}</small>
      <strong>${escapeHtml(title)}</strong>
      <em>${escapeHtml(body)}</em>
    </span>
  </a>`;
}

function profileChannelFallbackText(primary: string | null | undefined, secondary: string | null | undefined, fallback: string): string {
  const primaryText = primary?.trim();
  if (primaryText) return primaryText;
  const secondaryText = secondary?.trim();
  if (secondaryText) return secondaryText;
  return fallback;
}

function homeObservationNeedsId(item: HomeSnapshot["recentObservations"][number]): boolean {
  const name = (item.displayName || item.aiCandidateName || "").trim();
  return item.isAiCandidate === true
    || item.identificationCount === 0
    || name === ""
    || name === "同定待ち"
    || /未同定|名前待ち|unknown|unresolved|awaiting id/iu.test(name);
}

function renderHomeChannelDashboard(basePath: string, snapshot: HomeSnapshot): string {
  const isPersonalHome = Boolean(snapshot.viewerUserId);
  const latest = snapshot.recentObservations[0] ?? null;
  const firstPlace = snapshot.myPlaces[0] ?? null;
  const secondPlace = snapshot.myPlaces[1] ?? null;
  const latestHref = latest ? profileObservationHref(basePath, latest) : withBasePath(basePath, "/record");
  const needsIdCount = snapshot.recentObservations.filter(homeObservationNeedsId).length;
  const continueHref = isPersonalHome && latest ? latestHref : withBasePath(basePath, "/records?view=mine");
  const placeHref = withBasePath(basePath, isPersonalHome && (secondPlace || firstPlace) ? "/records?view=places" : "/map");
  const placeTitle = secondPlace?.placeName ?? firstPlace?.placeName ?? (isPersonalHome ? "地図から探す" : "近くの発見を見る");
  const placeBody = secondPlace
    ? buildPlaceNextLine(secondPlace)
    : firstPlace
      ? buildPlaceNextLine(firstPlace)
      : isPersonalHome
        ? "近くの発見から、次に歩く場所を選ぶ"
        : "地域の記録から、最初に歩く場所を決める";
  const recordCountLabel = isPersonalHome
    ? `${formatProfileNumber(snapshot.recentObservations.length)} 件`
    : "公開記録";
  const placeCountLabel = isPersonalHome
    ? `${formatProfileNumber(snapshot.myPlaces.length)} か所`
    : "地域";
  const heroTitle = isPersonalHome ? "観察ノート" : "今日のikimon.life";
  const heroLead = isPersonalHome
    ? "自分が見た場所、前回の発見、名前を確かめたい記録を、続きから読み返すための個人ホームです。"
    : "見つけた自然を残し、地域の記録から次に歩く場所を選べます。";
  const continueItems = isPersonalHome
    ? [
        {
          href: continueHref,
          label: latest ? "続きから" : "記録棚",
          value: latest?.displayName ?? "まだ記録はありません",
          body: latest ? `${formatProfileDate(latest.observedAt)} · ${latest.placeName}` : "自分の記録が入る場所を先に確認できます。",
        },
        {
          href: withBasePath(basePath, "/records?view=needs_id"),
          label: "名前を確かめる",
          value: `${formatProfileNumber(needsIdCount)} 件`,
          body: needsIdCount > 0 ? "候補名や証拠を見ながら確認できます。" : "名前が揺れている記録はここに集まります。",
        },
        {
          href: placeHref,
          label: "再訪する場所",
          value: placeTitle,
          body: placeBody,
        },
      ]
    : [];
  const homeActionCards = latest
    ? isPersonalHome
      ? [
          {
            href: latestHref,
            label: "前回を見る",
            title: latest.displayName,
            body: `${formatProfileDate(latest.observedAt)} · ${latest.placeName}`,
            primary: true,
          },
          {
            href: withBasePath(basePath, "/records?view=mine"),
            label: "記録棚",
            title: `${formatProfileNumber(snapshot.recentObservations.length)} 件`,
            body: "写真と場所を、後から探しやすい形で読み返す",
            primary: false,
          },
          {
            href: placeHref,
            label: "地図で見る",
            title: placeTitle,
            body: placeBody,
            primary: false,
          },
        ]
      : [
          {
            href: placeHref,
            label: "場所を探す",
            title: placeTitle,
            body: placeBody,
            primary: true,
          },
          {
            href: withBasePath(basePath, "/records"),
            label: "みんなの記録",
            title: "公開記録を見る",
            body: "写真と場所から、地域の自然を読み返す",
            primary: false,
          },
          {
            href: latestHref,
            label: "最近の記録",
            title: latest.displayName,
            body: `${formatProfileDate(latest.observedAt)} · ${latest.placeName}`,
            primary: false,
          },
        ]
    : [
        {
          href: placeHref,
          label: isPersonalHome ? "地図で見る" : "場所を探す",
          title: placeTitle,
          body: placeBody,
          primary: true,
        },
        {
          href: withBasePath(basePath, isPersonalHome ? "/records?view=mine" : "/records"),
          label: isPersonalHome ? "記録棚" : "みんなの記録",
          title: isPersonalHome ? "まだ記録はありません" : "公開記録を見る",
          body: isPersonalHome ? "自分の記録が入る場所を先に確認できます。" : "写真と場所から、地域の自然を読み返す",
          primary: false,
        },
        {
          href: withBasePath(basePath, "/record"),
          label: "フッターから記録",
          title: firstPlace?.placeName ?? "いま見つけたもの",
          body: firstPlace ? "同じ場所で次の観察を残す" : "外では画面下の記録ボタンから始められます。",
          primary: false,
        },
      ];
  return `<section class="section home-mypage-section" data-testid="home-channel">
    <div class="home-workbench" aria-label="${escapeHtml(isPersonalHome ? "マイページ操作" : "はじめる操作")}">
      <div class="home-mypage-hero">
        <div class="home-mypage-copy">
          <div class="eyebrow">${escapeHtml(isPersonalHome ? "マイページ" : "Local nature")}</div>
          <h1>${escapeHtml(heroTitle)}</h1>
          <p>${escapeHtml(heroLead)}</p>
          <div class="home-mypage-cta">
            <a class="home-mypage-button is-primary" href="${escapeHtml(isPersonalHome ? continueHref : withBasePath(basePath, "/map"))}">${escapeHtml(isPersonalHome ? "続きから読む" : "近くを見る")}</a>
            <a class="home-mypage-button" href="${escapeHtml(isPersonalHome ? withBasePath(basePath, "/records?view=needs_id") : withBasePath(basePath, "/records"))}">${escapeHtml(isPersonalHome ? "名前を確かめる" : "記録を見る")}</a>
          </div>
          ${continueItems.length > 0 ? `<div class="home-continue-strip" aria-label="続きから">
            ${continueItems.map((item) => `<a href="${escapeHtml(item.href)}">
              <span>${escapeHtml(item.label)}</span>
              <strong>${escapeHtml(item.value)}</strong>
              <em>${escapeHtml(item.body)}</em>
            </a>`).join("")}
          </div>` : ""}
        </div>
        <div class="home-today-panel" aria-label="${escapeHtml(isPersonalHome ? "今日の入口" : "今日の入口")}">
          <div class="home-today-head">
            <span>今日の入口</span>
            <strong>${escapeHtml(isPersonalHome && latest ? latest.displayName : "地域の記録から始める")}</strong>
            <em>${escapeHtml(isPersonalHome && latest ? `${formatProfileDate(latest.observedAt)} · ${latest.placeName}` : "地域の記録や地図から、次に歩く場所を選べます。")}</em>
          </div>
          <div class="home-action-grid">
            ${homeActionCards.map((card) => `<a class="home-action-card${card.primary ? " is-primary" : ""}" href="${escapeHtml(card.href)}">
              <span>${escapeHtml(card.label)}</span>
              <strong>${escapeHtml(card.title)}</strong>
              <em>${escapeHtml(card.body)}</em>
            </a>`).join("")}
          </div>
        </div>
      </div>
      <div class="home-mypage-rail" aria-label="ikimon.lifeの流れ">
        <a href="${escapeHtml(withBasePath(basePath, "/record"))}"><span>フッターから</span><strong>記録する</strong></a>
        <a href="${escapeHtml(withBasePath(basePath, "/records?view=mine"))}"><span>${escapeHtml(recordCountLabel)}</span><strong>自分の記録</strong></a>
        <a href="${escapeHtml(placeHref)}"><span>${escapeHtml(placeCountLabel)}</span><strong>地図・場所</strong></a>
        <a href="${escapeHtml(withBasePath(basePath, "/profile"))}"><span>公開面</span><strong>プロフィール</strong></a>
      </div>
    </div>
  </section>`;
}

export function renderHomePageHtml(basePath: string, lang: SiteLang, snapshot: HomeSnapshot, showSpecialistCta = false): string {
  const cards = snapshot.recentObservations.map((item) =>
    renderObservationCard(basePath, lang, {
      occurrenceId: item.occurrenceId,
      visitId: item.visitId,
      detailId: item.detailId,
      featuredOccurrenceId: item.featuredOccurrenceId,
      featuredSubjectName: item.featuredSubjectName,
      subjectCount: item.subjectCount,
      isMultiSubject: item.isMultiSubject,
      featuredConfidenceBand: item.featuredConfidenceBand,
      displayStability: item.displayStability,
      displayName: item.displayName,
      observedAt: item.observedAt,
      observerName: item.observerName,
      placeName: item.placeName,
      municipality: item.municipality,
      publicLocation: item.publicLocation,
      photoUrl: item.photoUrl,
      mediaUrl: item.mediaUrl,
      hasPhoto: item.hasPhoto,
      hasVideo: item.hasVideo,
      identificationCount: item.identificationCount,
      latitude: null,
      longitude: null,
      observerUserId: null,
      observerAvatarUrl: null,
    }, { locationMode: "public", showSpecialistCta, compact: true }),
  ).join("");
  const myPlaces = renderPlaceRows(
    basePath,
    lang,
    snapshot.viewerUserId,
    snapshot.myPlaces,
    "まだ記録した場所はありません。",
  );
  const recentHeading = snapshot.viewerUserId ? "自分の最近の観察" : "みんなの最近の観察";
  const recentHref = snapshot.viewerUserId ? "/records?view=mine" : "/records";
  return layout(
    basePath,
    snapshot.viewerUserId ? "マイページ | ikimon" : "ホーム | ikimon",
    `${renderHomeChannelDashboard(basePath, snapshot)}
      <section class="section"><div class="section-header"><div><div class="eyebrow">記録</div><h2>${escapeHtml(recentHeading)}</h2></div><a class="section-link" href="${escapeHtml(withBasePath(basePath, recentHref))}">すべて見る</a></div><div class="home-grid">${cards}</div></section>
      ${snapshot.viewerUserId ? `<section class="section"><div class="section-header"><div><div class="eyebrow">場所</div><h2>再訪したい場所</h2></div><a class="section-link" href="${escapeHtml(withBasePath(basePath, "/records?view=places"))}">場所を見る</a></div><div class="list">${myPlaces}</div></section>` : ""}`,
    "ホーム",
    undefined,
    `${OBSERVATION_CARD_STYLES}
        .home-workbench { min-width: 0; display: grid; gap: 14px; }
        .home-mypage-hero { min-width: 0; display: grid; grid-template-columns: minmax(0, 1.06fr) minmax(320px, .94fr); gap: 14px; align-items: stretch; }
        .home-mypage-copy { min-width: 0; display: grid; align-content: center; gap: 12px; padding: 24px; border-radius: 16px; background: #10251a; color: #fff; box-shadow: 0 18px 40px rgba(16,37,26,.16); }
        .home-mypage-copy .eyebrow { color: #a7f3d0; opacity: 1; letter-spacing: 0; text-transform: none; font-size: 13px; font-weight: 950; }
        .home-mypage-copy h1 { margin: 0; font-size: 34px; line-height: 1.12; letter-spacing: 0; }
        .home-mypage-copy p { margin: 0; max-width: 620px; color: #d1fae5; font-size: 16px; line-height: 1.62; font-weight: 700; }
        .home-mypage-cta { display: flex; flex-wrap: wrap; gap: 10px; }
        .home-mypage-button { min-height: 46px; display: inline-flex; align-items: center; justify-content: center; padding: 10px 16px; border-radius: 999px; background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.2); color: #fff; text-decoration: none; font-size: 15px; font-weight: 950; }
        .home-mypage-button.is-primary { background: #10b981; border-color: #10b981; color: #052e1c; }
        .home-continue-strip { min-width: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 2px; }
        .home-continue-strip a { min-width: 0; min-height: 92px; display: grid; align-content: start; gap: 5px; padding: 11px; border-radius: 8px; background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.18); color: #fff; text-decoration: none; overflow-wrap: anywhere; }
        .home-continue-strip a:hover,
        .home-continue-strip a:focus-visible { background: rgba(255,255,255,.16); outline: none; }
        .home-continue-strip span { color: #a7f3d0; font-size: 11px; line-height: 1.2; font-weight: 950; }
        .home-continue-strip strong { color: #fff; font-size: 15px; line-height: 1.25; font-weight: 950; }
        .home-continue-strip em { color: #d1fae5; font-size: 12px; line-height: 1.45; font-style: normal; font-weight: 720; }
        .home-today-panel { min-width: 0; display: grid; gap: 12px; padding: 16px; border-radius: 16px; border: 1px solid rgba(15,23,42,.08); background: rgba(255,255,255,.94); box-shadow: 0 14px 32px rgba(15,23,42,.06); }
        .home-today-head { min-width: 0; display: grid; gap: 4px; }
        .home-today-head span { color: #047857; font-size: 13px; line-height: 1.2; font-weight: 950; }
        .home-today-head strong { color: #10251a; font-size: 21px; line-height: 1.25; font-weight: 950; overflow-wrap: anywhere; }
        .home-today-head em { color: #475569; font-size: 14px; line-height: 1.45; font-style: normal; font-weight: 750; }
        .home-action-grid { min-width: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
        .home-action-card { min-width: 0; min-height: 120px; display: grid; align-content: start; gap: 7px; padding: 14px; border-radius: 8px; border: 1px solid rgba(15,23,42,.08); background: #f8fafc; box-shadow: 0 10px 24px rgba(15,23,42,.045); color: inherit; text-decoration: none; overflow-wrap: anywhere; }
        .home-action-card:hover { transform: translateY(-1px); box-shadow: 0 14px 28px rgba(15,23,42,.075); }
        .home-action-card span { color: #047857; font-size: 12px; line-height: 1.2; font-weight: 950; }
        .home-action-card strong { color: #10251a; font-size: 16px; line-height: 1.35; font-weight: 950; }
        .home-action-card em { color: #475569; font-size: 13px; line-height: 1.5; font-style: normal; font-weight: 720; }
        .home-action-card.is-primary { background: #047857; border-color: #047857; color: #fff; }
        .home-action-card.is-primary span,
        .home-action-card.is-primary strong,
        .home-action-card.is-primary em { color: #fff; }
        .home-mypage-rail { min-width: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
        .home-mypage-rail a { min-width: 0; min-height: 58px; display: grid; align-content: center; gap: 3px; padding: 11px 13px; border-radius: 12px; border: 1px solid rgba(15,23,42,.08); background: #fff; color: #10251a; text-decoration: none; box-shadow: 0 8px 20px rgba(15,23,42,.04); }
        .home-mypage-rail span { color: #64748b; font-size: 12px; line-height: 1.25; font-weight: 850; }
        .home-mypage-rail strong { font-size: 15px; line-height: 1.25; font-weight: 950; overflow-wrap: anywhere; }
        .home-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 12px; align-items: start; }
        .home-grid .obs-card { border-radius: 8px; box-shadow: 0 8px 20px rgba(15,23,42,.045); }
        .home-grid .obs-card:hover { transform: translateY(-1px); box-shadow: 0 12px 24px rgba(15,23,42,.075); }
        .home-grid .obs-card-media { aspect-ratio: 16 / 10; }
        .home-grid .obs-card-meta { padding: 10px 12px 12px; }
        .home-grid .obs-card-place { -webkit-line-clamp: 1; }
        .home-grid .obs-card-actions { display: none; }
        @media (max-width: 980px) {
          .home-mypage-hero { grid-template-columns: 1fr; }
          .home-action-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
          .home-continue-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }
          .home-mypage-rail { grid-template-columns: repeat(2, minmax(0, 1fr)); }
        }
        @media (max-width: 620px) {
          .home-mypage-copy { padding: 16px; border-radius: 14px; gap: 9px; }
          .home-mypage-copy h1 { font-size: 28px; }
          .home-mypage-copy p { font-size: 14px; line-height: 1.55; }
          .home-continue-strip { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 2px; scrollbar-width: none; }
          .home-continue-strip::-webkit-scrollbar { display: none; }
          .home-continue-strip a { flex: 0 0 min(72vw, 210px); min-height: 72px; padding: 10px; }
          .home-today-panel { padding: 13px; gap: 9px; }
          .home-action-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
          .home-action-card:first-child { grid-column: 1 / -1; }
          .home-action-card { min-height: 78px; padding: 11px; gap: 5px; }
          .home-action-card strong { font-size: 15px; }
          .home-action-card em { font-size: 12px; line-height: 1.42; }
          .home-mypage-rail { grid-template-columns: 1fr; }
          .home-grid { grid-template-columns: repeat(auto-fill, minmax(158px, 1fr)); gap: 10px; }
          .home-grid .obs-card-attribution { font-size: 12px; }
          .home-grid .obs-card-when { display: none; }
        }
        ${PLACE_REVISIT_ROW_STYLES}
      `,
    appendLangToHref(withBasePath(basePath, "/home"), lang),
  );
}

function renderProfileChannelHero(basePath: string, snapshot: ProfileSnapshot): string {
  const latest = snapshot.recentObservations[0] ?? null;
  const firstPlace = snapshot.recentPlaces[0] ?? null;
  const topLife = snapshot.lifeListPreview[0] ?? null;
  const recordCountLabel = snapshot.stats.totalObservations > 0
    ? `${formatProfileNumber(snapshot.stats.totalObservations)}件`
    : "記録する";
  const placeCountLabel = snapshot.stats.placeCount > 0
    ? `${formatProfileNumber(snapshot.stats.placeCount)}か所`
    : "地図を見る";
  const lifeCountLabel = snapshot.stats.uniqueTaxaAllTime > 0
    ? `${formatProfileNumber(snapshot.stats.uniqueTaxaAllTime)}種`
    : recordCountLabel;
  return `<section class="section" data-testid="profile-channel">
    <div class="profile-channel-grid">
      ${renderChannelMediaCard(
        withBasePath(basePath, firstPlace ? "/records?view=places" : "/map"),
        "自分のフィールド",
        firstPlace?.placeName ?? "これから歩く場所",
        firstPlace ? buildPlaceNextLine(firstPlace) : "場所の記録が入ると、よく歩くフィールドとして育ちます。",
        latest?.photoUrl,
        profileChannelFallbackText(firstPlace?.placeName, firstPlace?.municipality, placeCountLabel),
      )}
      ${renderChannelMediaCard(
        latest ? profileObservationHref(basePath, latest) : withBasePath(basePath, "/record"),
        "最近の記録",
        latest?.displayName ?? "まだ記録はありません",
        latest ? `${formatProfileDate(latest.observedAt)} · ${latest.placeName}` : "最初の発見から、自然との関わりが見えるページになります。",
        latest?.photoUrl,
        profileChannelFallbackText(latest?.displayName, latest?.placeName, recordCountLabel),
      )}
      ${renderChannelMediaCard(
        withBasePath(basePath, firstPlace ? "/record" : "/map"),
        "次に行く場所",
        firstPlace ? buildPlaceNextLine(firstPlace) : "地図から探す",
        firstPlace ? `${firstPlace.placeName} をもう一度見る理由があります。` : "近くの発見から、次の観察地点を選べます。",
        null,
        profileChannelFallbackText(firstPlace?.nextLookFor, firstPlace?.latestDisplayName, firstPlace?.placeName ?? placeCountLabel),
      )}
      ${renderChannelMediaCard(
        withBasePath(basePath, "/records?view=mine"),
        "自分の図鑑",
        topLife?.displayName ?? "名前が付くと並びます",
        topLife ? `${formatProfileNumber(topLife.observationCount)} 件の記録から見返せます。` : "同定が進むほど、自分だけの Life List が育ちます。",
        topLife?.photoUrl ?? latest?.photoUrl,
        profileChannelFallbackText(topLife?.displayName, latest?.displayName, lifeCountLabel),
      )}
    </div>
  </section>`;
}

function renderProfileNextActions(basePath: string, snapshot: ProfileSnapshot, digest: ProfileNoteDigest | null = null): string {
  const firstPlace = snapshot.recentPlaces[0] ?? null;
  const latestObservation = snapshot.recentObservations[0] ?? null;
  const latestHref = latestObservation
    ? withBasePath(basePath, buildObservationDetailPath(
      latestObservation.detailId ?? latestObservation.visitId ?? latestObservation.occurrenceId,
      latestObservation.featuredOccurrenceId ?? latestObservation.occurrenceId,
    ))
    : withBasePath(basePath, "/records?view=mine");
  const latestBody = digest?.todayReading || (latestObservation
    ? `${latestObservation.displayName} を見返すと、${latestObservation.placeName} の前回のページから読み始められます。`
    : "まだ自分の記録はありません。記録一覧や場所の章から、読み返し方を先に眺められます。");
  const placeBody = digest?.placeChapters[0]?.readingAngle || (firstPlace
    ? `${firstPlace.placeName} は ${firstPlace.visitCount} 回分の記憶があります。${buildPlaceNextLine(firstPlace)}。`
    : "場所が増えるほど、同じ道の季節差や小さな変化を章として読み返せます。");
  const learningBody = digest?.learningHighlight || "Life List は数ではなく、見分ける観点が増えてきた履歴として読み返せます。";
  const contributionBody = digest?.localContribution || `${formatProfileNumber(snapshot.stats.placeCount)} か所の記憶が、地域を読み返す手がかりを増やしています。`;
  const contributionValue = digest
    ? `${escapeHtml(formatProfileNumber(digest.sourceStats.observationCount))} ページ`
    : `${escapeHtml(formatProfileNumber(snapshot.stats.totalObservations))} ページ`;
  const needsNameCount = snapshot.recentObservations.filter(profileObservationNeedsName).length;
  const needsNameBody = needsNameCount > 0
    ? "写真やメモを見返すと、地域図鑑として読める記録に近づきます。"
    : "いま見える範囲の記録は、名前付きのページとして読み返せます。";
  return `<section class="section" data-testid="profile-next-actions">
    <div class="section-header"><div><div class="eyebrow">My history</div><h2>自分の記録史</h2></div></div>
    <div class="profile-reading-digest">
      <div class="profile-reading-main">
        <div class="eyebrow">Story</div>
        <h3>積み上がった時間から、今日の自分を読み直す</h3>
        <p>${escapeHtml(latestBody)}</p>
      </div>
      <div class="profile-reading-points">
        <div><span>はじまり</span><strong>${escapeHtml(formatProfileDate(snapshot.stats.firstObservedAt))}</strong><p>${escapeHtml(snapshot.stats.firstObservedAt ? `${profileObservationYears(snapshot)} 年分の記録史として読み返せます。` : "最初の記録が入ると、ここから自分の歴史が始まります。")}</p></div>
        <div><span>見えてきたこと</span><strong>${escapeHtml(formatProfileNumber(snapshot.stats.uniqueTaxaAllTime))} 種を見てきた</strong><p>${escapeHtml(learningBody)}</p></div>
        <div><span>地域への手がかり</span><strong>${contributionValue}</strong><p>${escapeHtml(contributionBody)}</p></div>
        <div><span>名前待ち</span><strong>${escapeHtml(formatProfileNumber(needsNameCount))} 件</strong><p>${escapeHtml(needsNameBody)}</p></div>
      </div>
      <div class="profile-reading-actions">
        <a class="btn btn-solid" href="${escapeHtml(latestHref)}">前回のページを読む</a>
        <a class="btn btn-ghost" href="${escapeHtml(withBasePath(basePath, "/records?view=mine"))}">記録一覧を見る</a>
        <a class="btn btn-ghost" href="${escapeHtml(withBasePath(basePath, "/records?view=needs_id"))}">名前待ちを見る</a>
        <a class="btn btn-ghost" href="${escapeHtml(withBasePath(basePath, "/guide/outcomes"))}">ガイド成果を見る</a>
        <a class="btn btn-ghost" href="${escapeHtml(withBasePath(basePath, "/records?view=places"))}">場所を見る</a>
      </div>
    </div>
  </section>`;
}

function renderProfileHistory(snapshot: ProfileSnapshot): string {
  const latest = snapshot.recentObservations[0] ?? null;
  const firstPlace = snapshot.recentPlaces[0] ?? null;
  const years = profileObservationYears(snapshot);
  const revisitCount = profileRevisitCount(snapshot);
  return `<section class="section" data-testid="profile-history">
    <div class="section-header"><div><div class="eyebrow">Timeline</div><h2>積み上がった履歴</h2></div></div>
    <div class="profile-history-shell">
      <div class="profile-history-line">
        <div class="profile-history-step"><span>最初の記録</span><strong>${escapeHtml(formatProfileDate(snapshot.stats.firstObservedAt))}</strong><p>${escapeHtml(years > 0 ? `${years} 年分の記録として残っています。` : "ここから記録の履歴が始まります。")}</p></div>
        <div class="profile-history-step"><span>最近のページ</span><strong>${escapeHtml(latest?.displayName ?? "これから")}</strong><p>${escapeHtml(latest ? `${latest.placeName} の ${formatProfileDate(latest.observedAt)} の記録。` : "記録が入ると、前回のページとして読めます。")}</p></div>
        <div class="profile-history-step"><span>再訪</span><strong>${escapeHtml(formatProfileNumber(revisitCount))} 回</strong><p>${escapeHtml(firstPlace ? `${firstPlace.placeName} など、同じ場所を重ねて見ています。` : "同じ場所をもう一度見るほど、変化が読めます。")}</p></div>
        <div class="profile-history-step"><span>今月</span><strong>${escapeHtml(formatProfileNumber(snapshot.stats.thisMonthObservations))} 件</strong><p>最近の関心がどこに向いているかを示す短い章です。</p></div>
      </div>
    </div>
  </section>`;
}

function renderProfileGrowth(snapshot: ProfileSnapshot, digest: ProfileNoteDigest | null = null): string {
  const topLife = snapshot.lifeListPreview.slice(0, 6);
  return `<section class="section" data-testid="profile-growth">
    <div class="section-header"><div><div class="eyebrow">Growth</div><h2>前より見えてきたこと</h2></div></div>
    <div class="profile-growth-shell">
      <div class="profile-growth-grid">
        <div class="profile-growth-card"><span>Life List</span><strong>${escapeHtml(formatProfileNumber(snapshot.stats.uniqueTaxaAllTime))} 種</strong><p>数を競うためではなく、見分ける観点が増えてきた履歴です。</p></div>
        <div class="profile-growth-card"><span>手がかりが濃い記録</span><strong>${escapeHtml(formatProfileNumber(snapshot.stats.tier2PlusCount))} 件</strong><p>写真や文脈が残り、あとから確かめやすい記録です。</p></div>
        <div class="profile-growth-card"><span>学びの要約</span><strong>${escapeHtml(digest ? "更新済み" : "準備中")}</strong><p>${escapeHtml(digest?.learningHighlight || "記録が増えるほど、よく見る生きものや名前が揺れている対象を要約できます。")}</p></div>
      </div>
      ${topLife.length > 0
        ? `<div class="profile-life-strip">${topLife.map((item) => `<span class="profile-life-pill">${escapeHtml(item.displayName)}</span>`).join("")}</div>`
        : `<div class="profile-life-strip"><span class="profile-life-pill">名前が付くとここに並びます</span></div>`}
    </div>
  </section>`;
}

function renderProfilePlaceStories(stories: RegionalStoryCue[]): string {
  const distinctStories = dedupeProfileRegionalStories(stories, 2);
  if (distinctStories.length === 0) return "";
  return `<section class="section" data-testid="profile-place-stories">
    <div class="section-header"><div><div class="eyebrow">Place relationship</div><h2>自分と場所の関係史</h2></div></div>
    <div class="profile-place-story-list">
      ${distinctStories.map((story) => renderRegionalStoryPanel(story, "profile")).join("")}
    </div>
  </section>`;
}

export function profileRegionalStoryInputForPlace(
  viewerUserId: string,
  place: Pick<HomePlace, "placeId" | "placeName" | "municipality" | "latitude" | "longitude" | "latestDisplayName" | "nextLookFor" | "lastObservedAt">,
): RegionalStoryInput {
  const latestDisplayName = String(place.latestDisplayName ?? "").trim();
  const nextLookFor = String(place.nextLookFor ?? "").trim();
  const subjectContext = latestDisplayName || nextLookFor;
  const lastObservedAt = String(place.lastObservedAt ?? "").trim();
  return {
    surface: "profile",
    viewerUserId,
    place: {
      placeId: place.placeId,
      placeName: place.placeName,
      municipality: place.municipality,
      latitude: place.latitude,
      longitude: place.longitude,
      publicLabel: place.municipality,
      allowPrecisePlaceLabel: true,
    },
    observation: subjectContext || lastObservedAt
      ? {
          displayName: subjectContext || null,
          observedAt: lastObservedAt || null,
        }
      : undefined,
    maxCards: 1,
  };
}

function normalizeProfileStoryText(value: string | null | undefined): string {
  return String(value ?? "").normalize("NFKC").replace(/\s+/gu, " ").trim().toLowerCase();
}

function profileRegionalStoryDedupKey(story: RegionalStoryCue): string {
  const renderedStoryText = [
    story.placeHook,
    story.whyHere,
    story.nextObservationAngle,
    story.collectiveNote,
  ].map(normalizeProfileStoryText).filter(Boolean).join("|");
  return renderedStoryText || normalizeProfileStoryText(`${story.angleKey}|${story.usedCardIds.join(",")}`);
}

function dedupeProfileRegionalStories(stories: RegionalStoryCue[], maxCount: number): RegionalStoryCue[] {
  const seen = new Set<string>();
  const distinct: RegionalStoryCue[] = [];
  for (const story of stories) {
    // Profile story cards render the heading and body first, so dedupe on that text before showing several near-identical place prompts.
    const key = profileRegionalStoryDedupKey(story);
    if (seen.has(key)) continue;
    seen.add(key);
    distinct.push(story);
    if (distinct.length >= maxCount) break;
  }
  return distinct;
}

